contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry with parameters: choose a target, value, and calldata for sendMoney
    function run(address target, uint256 value, bytes calldata data) public payable {
        require(true);

        // Read who is the owner of c before any call
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = address(c).balance;

        // Attempt withdrawAll, withdraw and sendMoney and capture whether they revert
        bool reverted_withdrawAll;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted_withdrawAll = true;
        } else {
            reverted_withdrawAll = false;
        }

        bool reverted_withdraw;
        c.withdraw(value); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            reverted_withdraw = true;
        } else {
            reverted_withdraw = false;
        }

        bool reverted_sendMoney;
        // ensure we have enough balance to attempt sending value from c if the call would succeed
        // (we do not fund c here; sendMoney uses c.call so it uses c's balance)
        c.sendMoney(target, value, data); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            reverted_sendMoney = true;
        } else {
            reverted_sendMoney = false;
        }

        // If any of the three calls succeeded (did not revert), then this contract must be the owner.
        // Also, if none succeeded, we permit that the caller is not the owner.
        bool anySucceeded = (!reverted_withdrawAll) || (!reverted_withdraw) || (!reverted_sendMoney);

        assert( anySucceeded == (ownerBefore == address(this)) );
    }

    // fallback to accept Ether if sent back during tests
    receive() external payable {}
}

