pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address target, uint256 value, bytes memory data) internal {
        vm.assume(true);
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        uint256 balanceBefore = address(c).balance;
        bool reverted_withdrawAll;
        try c.withdrawAll() {
            reverted_withdrawAll = false;
        } catch {
            reverted_withdrawAll = true;
        }
        bool reverted_withdraw;
        try c.withdraw(value) {
            reverted_withdraw = false;
        } catch {
            reverted_withdraw = true;
        }
        bool reverted_sendMoney;
        try c.sendMoney(target, value, data) {
            reverted_sendMoney = false;
        } catch {
            reverted_sendMoney = true;
        }
        bool anySucceeded = (!reverted_withdrawAll) || (!reverted_withdraw) || (!reverted_sendMoney);
        assertTrue(anySucceeded == (ownerBefore == address(this)));
    }

    function testFuzz_run(address target, uint256 value, bytes memory data) public {
        vm.assume(target.code.length == 0 && uint160(target) > 0xffff && target != address(this) && target != address(c) && target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && target != 0x000000000000000000636F6e736F6c652e6c6f67 && target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(target, value, data);
    }

    receive() external payable {}
}
